update sorting_item_translation set instruction = 'Jouets, boyaux d''arrosage et chaises de jardin ne vont pas au bac de récupération. Donnez-les s''ils servent encore; sinon, ce sont des déchets: le calendrier de la Ville définit le bac de déchets comme ce qui n''est ni recyclable, ni compostable, ni valorisable, ni dangereux.'
where language_code = 'fr' and item_id = (select i.id from sorting_item i join municipality m on m.id = i.municipality_id where m.slug = 'boisbriand' and i.item_key = 'broken-toy')
