update sorting_item_translation set name = 'Déchets excédentaires et meubles'
where language_code = 'fr' and item_id = (select i.id from sorting_item i join municipality m on m.id = i.municipality_id where m.slug = 'boisbriand' and i.item_key = 'bulky-items')
  and name = 'Dechets excedentaires et meubles';
update sorting_item_translation set instruction = 'Une fois par mois, le jour habituel de votre collecte, les déchets qui n''entrent pas dans le bac sont ramassés: meubles, petits électroménagers sans halocarbures, matériaux de construction sans clous, ensachés ou attachés, 23 kg par paquet, 5 m3 par adresse. En 2026, la dernière est du 15 au 18 décembre. Refusés: gros électroménagers et appareils réfrigérants, électroniques, pneus, résidus dangereux, troncs et souches. Un meuble encore bon: le Grenier populaire le ramasse à domicile.'
where language_code = 'fr' and item_id = (select i.id from sorting_item i join municipality m on m.id = i.municipality_id where m.slug = 'boisbriand' and i.item_key = 'bulky-items')
  and instruction = 'Une fois par mois, le jour habituel de votre collecte, les dechets qui n''entrent pas dans le bac sont ramasses: meubles, petits electromenagers sans halocarbures, materiaux de construction sans clous, ensaches ou attaches, 23 kg par paquet, 5 m3 par adresse. En 2026, la derniere est du 15 au 18 decembre. Refuses: gros electromenagers et appareils refrigerants, electroniques, pneus, residus dangereux, troncs et souches. Un meuble encore bon: le Grenier populaire le ramasse a domicile.';
update sorting_item_translation set availability = 'Une fois par mois, le jour habituel de votre collecte. En bordure de la chaussée dès 18 h la veille ou avant 7 h le jour même.'
